import streamlit as st

from . import loaders
from .components import not_available, section, synthetic_dataset_banner


def render():
    st.title("Dataset Analytics")
    synthetic_dataset_banner()
    st.caption(
        "Tables/charts below were generated by the M1 pipeline as designed against CICIDS2017-shaped "
        "data; on this machine that input was the synthetic placeholder described above."
    )

    section("Cleaning summary")
    summary = loaders.load_csv("results", "m1_dataset_preparation", "tables", "m1_dataset_summary.csv")
    if summary is not None:
        st.table(summary)
    else:
        not_available("results/m1_dataset_preparation/tables/m1_dataset_summary.csv not found")

    section("Class distribution")
    col1, col2 = st.columns([1, 1])
    with col1:
        class_dist = loaders.load_csv("results", "m1_dataset_preparation", "tables", "m1_class_distribution.csv")
        if class_dist is not None:
            st.dataframe(class_dist, use_container_width=True)
        else:
            not_available("results/m1_dataset_preparation/tables/m1_class_distribution.csv not found")
    with col2:
        img = loaders.load_image_path("results", "m1_dataset_preparation", "charts", "m1_class_distribution.png")
        if img:
            st.image(img, use_container_width=True)
        else:
            not_available("m1_class_distribution.png not found")

    section("Dataset reduction stages")
    img = loaders.load_image_path("results", "m1_dataset_preparation", "charts", "m1_dataset_reduction.png")
    if img:
        st.image(img, use_container_width=True)
    else:
        not_available("m1_dataset_reduction.png not found")

    section("Prepared subsets")
    subset_summary = loaders.load_csv("results", "m1_dataset_preparation", "tables", "m1_subset_summary.csv")
    if subset_summary is not None:
        st.dataframe(subset_summary, use_container_width=True)
    else:
        not_available("results/m1_dataset_preparation/tables/m1_subset_summary.csv not found")

    img = loaders.load_image_path("results", "m1_dataset_preparation", "charts", "m1_processed_subsets.png")
    if img:
        st.image(img, use_container_width=True)
